def fm(e,v,u,a=()): return dict(expression=e,variables=v,units=u,assumptions=list(a))
def concept(p,title,description,pages=None):
 cid=f'{BATCH}-P{p:04}-C01';c=dict(id=cid,title=title,description=description,slideIds=[f'lectures-p{x:04}' for x in (pages or [p])],questionIds=[],status='drafted',topic=TITLE,subtopic=title,prerequisiteConceptIds=[],examinationAngles=[]);C.append(c);return c

def ask(c,stem,opts,why,*,correct=(0,),kind='conceptual',difficulty='easy',steps=(),assumptions=(),pages=None,formula=(),conflict=None):
 p=int(c['id'].split('-P')[1].split('-')[0]);i=1+sum(q['id'].startswith(f'{BATCH}-P{p:04}-Q') for q in Q);qid=f'{BATCH}-P{p:04}-Q{i:02}'
 assert len(opts)==len(why)==4
 ids=[f'o{j+1}' for j in range(4)];oo=[dict(id=k,text=v) for k,v in zip(ids,opts)];shift=int(hashlib.sha256(qid.encode()).hexdigest()[:4],16)%4;oo=oo[shift:]+oo[:shift]
 ps=pages or [int(s.split('p')[1]) for s in c['slideIds']]
 cites=[]
 for n in ps:
  cites.append(dict(slideId=f'lectures-p{n:04}',sourceId='lectures',sourceSha256=SHA,physicalPage=n,kind='code' if n in (499,500) else 'figure' if kind=='diagram' else 'derivation' if kind=='numerical' else 'statement',locator=f'Printed slide {n-577}: {LOC[n]}',evidenceText=(CODE.split('# Plot')[0].strip() if n==499 else '# Plot'+CODE.split('# Plot',1)[1]) if n in (499,500) else TEXT[n],role='conflict' if conflict and n==conflict[0] else 'premise' if kind in ('numerical','code_output','algorithm_trace') or formula else 'explicit',region=None))
 just=' '.join(why[j] for j in correct)
 q=dict(id=qid,version=1,status='draft',authorId=AUTHOR,stem=stem,selectionMode='multi' if len(correct)>1 else 'single',type=kind,difficulty=difficulty,cognitiveSkill='numerical' if kind=='numerical' else 'algorithm' if kind in ('code_output','algorithm_trace') else 'application' if kind in ('scenario','diagram') else 'recall' if difficulty=='easy' else 'conceptual',week=4,lectureId='L19',topic=TITLE,subtopic=c['title'],tags=['trajectory-planning','joint-space',c['title']],conceptIds=[c['id']],assumptions=list(assumptions),options=oo,correctOptionIds=[ids[j] for j in correct],citations=cites,solution=dict(justification=just,optionExplanations={k:('Correct. ' if j in correct else 'Incorrect. ')+why[j] for j,k in enumerate(ids)},steps=list(steps),formulas=list(formula),simpleExplanation=just,memoryAid=None,misconceptions=[why[j] for j in range(4) if j not in correct],examTraps=[],prerequisiteConceptIds=[]),origin='generated',reviewIds=[])
 if conflict:
  n,claim,basis=conflict
  q['conflictResolution']=dict(status='derived-qualification-pending-independent-review',questionVersion=1,sourceId='lectures',sourceSha256=SHA,physicalPage=n,sourceClaim=claim,basis=basis,method='Apply the cited definitions/equations under the assumptions explicitly stated in this question; author calculations are separately recorded.',scope='This draft question only. Source PDF unchanged; independent review required.')
 Q.append(q);c['questionIds'].append(qid);c['examinationAngles'].append(stem);return q

def issue(p,key,claim,handling):issues.append(dict(id=f'L19-ISSUE-{p}-{key}',physicalPage=p,sourceId='lectures',sourceSha256=SHA,finding=claim,handling=handling,status='explicitly_scoped_pending_independent_review'))
