  write('audits/W04-L19-review-manifest.json',dict(batchId=BATCH,sourceSha256=SHA,blindPacket='audits/blind-W04-L19.json',blindPacketSha256=h,questionSha256=hashes,questions=len(Q),concepts=len(C),independentReviewPending=True))
