# Author-side option-quality pass before first independent packet freeze.
def revise(short,texts,why):
 q=next(q for q in Q if q['id']==BATCH+'-'+short)
 for o in q['options']:o['text']=texts[int(o['id'][1:])-1]
 q['solution'].update(justification=why[0],simpleExplanation=why[0],optionExplanations={f'o{i+1}':('Correct. ' if i==0 else 'Incorrect. ')+v for i,v in enumerate(why)},misconceptions=why[1:])
