# Exact symbolic and numerical author checks. These do not constitute review approval.
import sympy as sp
import random

def ck(name,actual,expected,method='Exact symbolic/rational calculation'):
 assert actual==expected,(name,actual,expected)
 checks.append(dict(name=name,actual=str(actual),expected=str(expected),passed=True,method=method))
ck('Stewart joint count',6+6+6,18)
ck('Stewart links',6*2+2,14)
ck('Stewart joint freedom sum',6*2+6*3+6*1,36)
ck('Stewart mobility',6*(14-18-1)+36,6)
leg=sp.Matrix([0,0,2])+sp.eye(3)*sp.Matrix([1,0,0])-sp.Matrix([1,0,0]);ck('leg length geometric norm',sp.sqrt(leg.dot(leg)),2)
ck('ideal gear speed torque power',(sp.Rational(100,5),5*2,sp.Rational(100,5)*5*2),(20,10,200))
ck('lossy gear torque',sp.Rational(4,5)*5*2,8)
ck('pulley ratio and speed',(sp.Rational(60,20),sp.Rational(12,3)),(3,4))
ck('series springs 100 and300',1/(sp.Rational(1,100)+sp.Rational(1,300)),75)
ck('parallel displacement',sp.Rational(40,100+300),sp.Rational(1,10))
ck('output-referred series stiffness',1/(1/(sp.Integer(3)**2*100)+sp.Rational(1,900)),450)
G,d,l=sp.symbols('G d l',positive=True);ks=G*sp.pi*d**4/(32*l)
ck('solid shaft diameter scaling',sp.simplify(ks.subs(d,2*d)/ks),16)
ck('solid shaft length scaling',sp.simplify(ks.subs(l,2*l)/ks),sp.Rational(1,2))
ck('solid shaft numerical stiffness',ks.subs({G:80*10**9,d:sp.Rational(2,100),l:sp.Rational(1,2)}),800*sp.pi)
b,r,Cg=sp.symbols('b r Cg',positive=True);kg=Cg*b*r*r
ck('gear width/radius scaling',sp.simplify(kg.subs({b:2*b,r:r/2})/kg),sp.Rational(1,2))
ki,eta,ti,di=sp.symbols('ki eta ti di',positive=True)
ck('gear stiffness referral',sp.simplify((eta*ti)/(di/eta)/(ti/di)),eta**2)
A,E=sp.symbols('A E',positive=True);kb=A*E/l
ck('belt stiffness unit-converted example',kb.subs({A:2*sp.Rational(1,10**6),E:10**9,l:sp.Rational(1,2)}),4000)
do,di,wo,wi=sp.symbols('do di wo wi',nonnegative=True)
kr=3*sp.pi*E*(do**4-di**4)/(64*l**3);kq=E*(wo**4-wi**4)/(4*l**3)
ck('round cantilever from3EI/l^3',sp.simplify(kr-3*E*(sp.pi*(do**4-di**4)/64)/l**3),0)
ck('square cantilever from3EI/l^3',sp.simplify(kq-3*E*((wo**4-wi**4)/12)/l**3),0)
ck('both beam length scalings',(sp.simplify(kr.subs(l,2*l)/kr),sp.simplify(kq.subs(l,2*l)/kq)),(sp.Rational(1,8),)*2)
ck('hollow retained stiffness ratio',1-sp.Rational(1,2)**4,sp.Rational(15,16))
ck('vanishing wall limit',sp.simplify(kr.subs(di,do)),0)
ck('motor torque',sp.Rational(4,10)*3,sp.Rational(6,5))
ck('position error',30-26,4)
s,bias=sp.symbols('s bias');ck('matched differential sensor',sp.expand(((s+bias)-(-s+bias))/2),s)
# Repeatability/domain tests for the algebraic families, not a synthetic-question count.
rng=random.Random(190605)
for _ in range(500):
 k1=sp.Rational(rng.randint(1,10000),10);k2=sp.Rational(rng.randint(1,10000),10)
 series=k1*k2/(k1+k2);parallel=k1+k2
 assert 0<series<min(k1,k2)<parallel
 outer=sp.Rational(rng.randint(2,100),100);inner=outer*sp.Rational(rng.randint(0,99),100)
 assert 0<outer**4-inner**4<=outer**4
 eta=sp.Rational(rng.randint(11,100),10);speed=sp.Rational(rng.randint(1,1000),10);torque=sp.Rational(rng.randint(1,1000),10)
 assert (speed/eta)*(torque*eta)==speed*torque
checks.append(dict(name='500 deterministic domain/algebra cases',seed=190605,passed=True,method='Positive series/parallel ordering, nondegenerate hollow-section positivity, and ideal gear power preservation using exact rationals.'))
